// PostServiceServer is the server API for PostService service.
// All implementations must embed UnimplementedPostServiceServer
// for forward compatibility.
type PostServiceServer interface {
	// Require an access token; the author is the caller. A post is deleted
	// by its author or by the owner of its wall; on a community's wall by
	// its admins too, whom post asks the club service about.
	CreatePost(context.Context, *CreatePostRequest) (*CreatePostResponse, error)
	DeletePost(context.Context, *DeletePostRequest) (*emptypb.Empty, error)
	// Requires an access token: shares a post on the caller's own wall. A
	// repost without text of a repost without text shares its original.
	RepostPost(context.Context, *RepostPostRequest) (*RepostPostResponse, error)
	// Requires an access token: the author changes the text and photos of
	// their post within a week of posting (editable_until); a repost keeps
	// what it shares and takes no photos.
	EditPost(context.Context, *EditPostRequest) (*EditPostResponse, error)
	// Require an access token: the owner of the wall (the admins of a
	// community) shows the post first on it, instead of the one pinned
	// before, or stops. Both idempotent.
	PinPost(context.Context, *PinPostRequest) (*emptypb.Empty, error)
	UnpinPost(context.Context, *UnpinPostRequest) (*emptypb.Empty, error)
	// Public: one post.
	GetPost(context.Context, *GetPostRequest) (*GetPostResponse, error)
	// Public: at most 50 posts by ID, for the notifications page; posts that
	// are gone are left out, the order is not kept.
	GetPosts(context.Context, *GetPostsRequest) (*GetPostsResponse, error)
	// Public: a user's wall, newest first, whoever wrote the posts.
	ListPosts(context.Context, *ListPostsRequest) (*ListPostsResponse, error)
	// Public: the posts written by several authors on any walls, but for
	// those that speak for a community, and every post on several walls,
	// newest first, for a news feed.
	ListFeed(context.Context, *ListFeedRequest) (*ListFeedResponse, error)
	// Require an access token; the caller likes the post. Both are
	// idempotent and return how many likes the post has now.
	LikePost(context.Context, *LikePostRequest) (*LikePostResponse, error)
	UnlikePost(context.Context, *UnlikePostRequest) (*UnlikePostResponse, error)
	// Require an access token; the author is the caller. A comment is
	// deleted by its author, by the author of the post or by the owner of
	// the wall, the admins of a community.
	CreateComment(context.Context, *CreateCommentRequest) (*CreateCommentResponse, error)
	DeleteComment(context.Context, *DeleteCommentRequest) (*emptypb.Empty, error)
	// Require an access token; the caller likes the comment. Both are
	// idempotent and return how many likes the comment has now.
	LikeComment(context.Context, *LikeCommentRequest) (*LikeCommentResponse, error)
	UnlikeComment(context.Context, *UnlikeCommentRequest) (*UnlikeCommentResponse, error)
	// Public: the comments of a post, oldest first.
	ListComments(context.Context, *ListCommentsRequest) (*ListCommentsResponse, error)
	// Public: at most 50 comments by ID, like GetPosts.
	GetComments(context.Context, *GetCommentsRequest) (*GetCommentsResponse, error)
	// Require an access token: posts suggested for a community's wall
	// ("Предложка" of openvk), seen only by their authors and the
	// community's admins, whom post asks the club service about. The caller
	// of SuggestPost has checked that the author may suggest there and that
	// the photos are theirs.
	SuggestPost(context.Context, *SuggestPostRequest) (*SuggestPostResponse, error)
	// The caller's own suggestions with mine; all of them for the admins.
	ListSuggestions(context.Context, *ListSuggestionsRequest) (*ListSuggestionsResponse, error)
	// An admin publishes a suggestion as a new post for the community.
	PublishSuggestion(context.Context, *PublishSuggestionRequest) (*PublishSuggestionResponse, error)
	// The author withdraws a suggestion, or an admin declines it.
	DeleteSuggestion(context.Context, *DeleteSuggestionRequest) (*emptypb.Empty, error)
	// The discussions of communities ("Обсуждения" of openvk). The caller
	// of CreateTopic has checked with the club service that the author may
	// start a topic there and, with from_wall, speak for the community, and
	// that the photos are theirs; the rest post asks the club service about.
	CreateTopic(context.Context, *CreateTopicRequest) (*CreateTopicResponse, error)
	// Public.
	GetTopic(context.Context, *GetTopicRequest) (*GetTopicResponse, error)
	// Public: the topics of a club, pinned first, then the most recently
	// active.
	ListTopics(context.Context, *ListTopicsRequest) (*ListTopicsResponse, error)
	// The author or an admin renames and closes a topic; only an admin pins
	// and restricts it.
	EditTopic(context.Context, *EditTopicRequest) (*EditTopicResponse, error)
	DeleteTopic(context.Context, *DeleteTopicRequest) (*emptypb.Empty, error)
	// Nobody writes in a closed topic, only the admins in a restricted one.
	// The caller has checked from_wall and the photos, as for CreateTopic.
	CreateTopicMessage(context.Context, *CreateTopicMessageRequest) (*CreateTopicMessageResponse, error)
	// Public: oldest first.
	ListTopicMessages(context.Context, *ListTopicMessagesRequest) (*ListTopicMessagesResponse, error)
	// Its author or an admin.
	DeleteTopicMessage(context.Context, *DeleteTopicMessageRequest) (*emptypb.Empty, error)
	// Photo albums of people and communities ("Альбомы" of openvk). An
	// album of the caller, without club_id, or of a community its admins
	// create, whom post asks the club service about.
	CreateAlbum(context.Context, *CreateAlbumRequest) (*CreateAlbumResponse, error)
	// Public.
	GetAlbum(context.Context, *GetAlbumRequest) (*GetAlbumResponse, error)
	// Public: the albums of a person or a community, newest first.
	ListAlbums(context.Context, *ListAlbumsRequest) (*ListAlbumsResponse, error)
	// Its owner or the admins of the community that owns it.
	EditAlbum(context.Context, *EditAlbumRequest) (*EditAlbumResponse, error)
	// With its photos; as EditAlbum.
	DeleteAlbum(context.Context, *DeleteAlbumRequest) (*emptypb.Empty, error)
	// Up to 10 photos the caller uploaded, which the caller of
	// AddAlbumPhotos has checked with the media service; as EditAlbum.
	AddAlbumPhotos(context.Context, *AddAlbumPhotosRequest) (*AddAlbumPhotosResponse, error)
	// Public: oldest first.
	ListAlbumPhotos(context.Context, *ListAlbumPhotosRequest) (*ListAlbumPhotosResponse, error)
	// Public: a photo with its album.
	GetAlbumPhoto(context.Context, *GetAlbumPhotoRequest) (*GetAlbumPhotoResponse, error)
	// Who uploaded the photo only.
	EditAlbumPhoto(context.Context, *EditAlbumPhotoRequest) (*EditAlbumPhotoResponse, error)
	// Who uploaded it or whoever may edit its album.
	DeleteAlbumPhoto(context.Context, *DeleteAlbumPhotoRequest) (*emptypb.Empty, error)
	// Internal, for user: the user's page was deleted and not restored in
	// time. Their posts and the posts on their wall go, with all their likes
	// and comments, and their likes and comments on others' posts. Idempotent.
	PurgeUser(context.Context, *PurgeUserRequest) (*emptypb.Empty, error)
	mustEmbedUnimplementedPostServiceServer()
}

